## Code Example
```javascript
// Playwright scaffold (pseudo)
const docId = `test_${Date.now()}`
const context1 = await browser.newContext()
const page1 = await context1.newPage()
const context2 = await browser.newContext()
const page2 = await context2.newPage()

// Setup: both users open same document
await page1.goto(`/editor/${docId}`)
await page2.goto(`/editor/${docId}`)

// Concurrent edits with latency injection
await page1.route('**/socket.io/**', route => {
  setTimeout(() => route.continue(), 100) // Inject 100ms latency
})

await page1.type('[contenteditable]', 'User 1 text')
await page2.type('[contenteditable]', 'User 2 text')

// Verify real-time updates and CRDT reconciliation
const finalContent1 = await page1.textContent('[contenteditable]')
const finalContent2 = await page2.textContent('[contenteditable]')
expect(finalContent1).toBe(finalContent2) // Deterministic final state
```

